export default function HomePage() {
/* Legacy Sites account flow retained in history during the Supabase migration.
  const [lang,setLang]=useState<Language>("en"); const [view,setView]=useState<View>("home"); const [onboarded,setOnboarded]=useState(false); const [editing,setEditing]=useState(false); const [savedJobs,setSavedJobs]=useState<number[]>([]); const [selectedJob,setSelectedJob]=useState(0); const [interested,setInterested]=useState(false); const [files,setFiles]=useState<string[]>([]); const [intakeStep,setIntakeStep]=useState(0); const [intakeAnswers,setIntakeAnswers]=useState<Record<string,string>>({}); const [intakeDocuments,setIntakeDocuments]=useState<Record<string,string>>({}); const [intakeDocumentFiles,setIntakeDocumentFiles]=useState<Record<string,File>>({}); const [intakeConsent,setIntakeConsent]=useState(false); const [intakeSubmitted,setIntakeSubmitted]=useState(false); const [intakeSaving,setIntakeSaving]=useState(false); const [intakeError,setIntakeError]=useState(""); const [account,setAccount]=useState<Account>(emptyAccount); const [accountLoading,setAccountLoading]=useState(true); const [accountError,setAccountError]=useState(""); const [profileSaving,setProfileSaving]=useState(false); const fileRef=useRef<HTMLInputElement>(null); const t=copy[lang]; const rtl=lang==="ar";
  useEffect(()=>{fetch("/api/me").then(async response=>{if(!response.ok)throw new Error(response.status===401?"signin":"load");return response.json()}).then(data=>{const next={...emptyAccount,...data,preferredLanguage:data.preferredLanguage??"en",onboardingCompleted:!!data.onboardingCompleted};setAccount(next);setLang(next.preferredLanguage);setOnboarded(!!next.onboardingCompleted||!!next.fullName)}).catch(error=>setAccountError(error.message)).finally(()=>setAccountLoading(false))},[]);
  const saveProfile=async(next:Account)=>{setProfileSaving(true);setAccountError("");try{const response=await fetch("/api/me",{method:"PUT",headers:{"content-type":"application/json"},body:JSON.stringify(next)});if(!response.ok)throw new Error("save");const saved={...emptyAccount,...await response.json()};setAccount(saved);setLang(saved.preferredLanguage);setEditing(false);setOnboarded(true)}catch{setAccountError("save")}finally{setProfileSaving(false)}};
  const changeLanguage=(next:Language)=>{setLang(next);if(account.id)void saveProfile({...account,preferredLanguage:next,fullName:account.fullName||account.displayName,onboardingCompleted:account.onboardingCompleted})};
  const openJob=(i:number)=>{setSelectedJob(i);setInterested(false);setView("job")};
  const submitIntake=async()=>{setIntakeSaving(true);setIntakeError("");try{await submitCandidateIntake({answers:intakeAnswers,documentFiles:intakeDocumentFiles,language:lang});setIntakeSubmitted(true)}catch(error){console.error(error);setIntakeError(persistenceCopy[lang].error)}finally{setIntakeSaving(false)}};
  if(accountLoading)return <main className="welcome-shell"><section className="welcome-card loading-card"><Brand/><div className="loading-mark"><ShieldCheck/></div><p className="lead">MediBridge Careers</p></section></main>;
  if(accountError==="signin")return <main className="welcome-shell"><section className="welcome-card signin-card"><Brand/><div><p className="eyebrow">MEDIBRIDGE CAREERS</p><h1>Secure candidate access</h1><p className="lead">Sign in to create and manage your candidate profile.</p></div><a className="primary-button" href="/signin-with-chatgpt?return_to=/">Sign in with ChatGPT<ArrowRight size={18}/></a></section></main>;
  if(!onboarded) return <main className="welcome-shell" dir={rtl?"rtl":"ltr"}><section className="welcome-card"><Brand/><div className="welcome-visual" aria-hidden="true"><div className="passport-card"><span>MB</span><BadgeCheck/></div><div className="journey-line"><span>✦</span></div><div className="germany-card"><span>DE</span><Check/></div></div><div><p className="eyebrow">MEDIBRIDGE CAREERS</p><h1>{t.welcome}</h1><p className="lead">{t.welcomeText}</p></div><div className="welcome-actions"><button className="primary-button" onClick={()=>{setOnboarded(true);setEditing(true);setView("profile")}}>{t.start}<ArrowRight size={18}/></button><button className="text-button" onClick={()=>setOnboarded(true)}>{t.haveAccount}</button></div><p className="privacy-line"><ShieldCheck size={16}/>{t.privacy}</p></section></main>;
  const focused=view==="job"||view==="intake"||view==="jobPreferences"||view==="settings"||view==="help";
  return <main className="app-shell" dir={rtl?"rtl":"ltr"}><div className="app-frame"><header className={`topbar ${focused?"focused":"main-header"}`}>{focused?<><button className="icon-button header-back" onClick={()=>view==="job"?setView("jobs"):setView("profile")} aria-label="Back"><ArrowLeft size={21}/></button><div className="header-brand"><Brand compact/></div><span className="header-spacer"/></>:<><div className="header-profile"><ProfileMenu lang={lang} setView={setView} account={account} compact/></div><div className="header-brand"><Brand compact/></div><button className="icon-button header-bell" aria-label="Notifications"><Bell size={20}/></button></>}</header><div className="page-content">{accountError&&<div className="app-error">{lang==="de"?"Änderungen konnten nicht gespeichert werden.":lang==="ar"?"تعذر حفظ التغييرات.":"Changes could not be saved."}</div>}{view==="home"&&<Dashboard t={t} lang={lang} account={account} submitted={intakeSubmitted} openJob={openJob} setView={setView}/>} {view==="jobs"&&<JobsList t={t} savedJobs={savedJobs} setSavedJobs={setSavedJobs} openJob={openJob}/>} {view==="documents"&&<Documents t={t} files={files} fileRef={fileRef} onFiles={(names:string[])=>setFiles(c=>[...c,...names])}/>} {view==="profile"&&<Profile t={t} editing={editing} setEditing={setEditing} setView={setView} lang={lang} submitted={intakeSubmitted} account={account} saving={profileSaving} onSave={saveProfile}/>} {view==="job"&&<JobDetail t={t} job={jobs[selectedJob]} interested={interested} setInterested={setInterested} saved={savedJobs.includes(selectedJob)} toggleSaved={()=>setSavedJobs(s=>s.includes(selectedJob)?s.filter(x=>x!==selectedJob):[...s,selectedJob])}/>} {view==="intake"&&<Intake lang={lang} step={intakeStep} setStep={setIntakeStep} answers={intakeAnswers} setAnswers={setIntakeAnswers} documents={intakeDocuments} setDocuments={setIntakeDocuments} setDocumentFiles={setIntakeDocumentFiles} consent={intakeConsent} setConsent={setIntakeConsent} submitted={intakeSubmitted} saving={intakeSaving} error={intakeError} onSubmit={submitIntake} onDone={()=>setView("home")}/>} {view==="jobPreferences"&&<JobPreferences lang={lang}/>} {view==="settings"&&<SettingsPage lang={lang} setLang={changeLanguage}/>} {view==="help"&&<HelpPage lang={lang}/>}</div>{!focused&&<BottomNav t={t} view={view} setView={setView}/>}</div></main>;
*/
  const [lang,setLang]=useState<Language>("en"); const [view,setView]=useState<View>("home"); const [onboarded,setOnboarded]=useState(false); const [loading,setLoading]=useState(true); const [savedJobs,setSavedJobs]=useState<number[]>([]); const [selectedJob,setSelectedJob]=useState(0); const [interested,setInterested]=useState(false); const [intakeStep,setIntakeStep]=useState(0); const [intakeAnswers,setIntakeAnswers]=useState<Record<string,string>>({}); const [intakeDocuments,setIntakeDocuments]=useState<Record<string,string>>({}); const [intakeDocumentFiles,setIntakeDocumentFiles]=useState<Record<string,File>>({}); const [intakeConsent,setIntakeConsent]=useState(false); const [intakeSubmitted,setIntakeSubmitted]=useState(false); const [intakeSaving,setIntakeSaving]=useState(false); const [intakeError,setIntakeError]=useState(""); const [status,setStatus]=useState<CandidateStatus>("draft"); const [reference,setReference]=useState(""); const [documents,setDocuments]=useState<CandidateDocument[]>([]); const [preferences,setPreferences]=useState<JobPreferences>({desired_role:"",preferred_region:"",possible_start:"",workplace:""}); const [draftState,setDraftState]=useState<"idle"|"saving"|"saved"|"error">("idle"); const loaded=useRef(false); const t=copy[lang]; const rtl=lang==="ar";
  const [liveJobs,setLiveJobs]=useState<Job[]>([]);const [interests,setInterests]=useState<JobInterest[]>([]);const [avatarUrl,setAvatarUrl]=useState("");const [avatarPath,setAvatarPath]=useState("");
  const account:Account={...emptyAccount,fullName:intakeAnswers.fullName||"",email:intakeAnswers.email||"",country:intakeAnswers.residence||"",profession:intakeAnswers.targetRole||"",experience:intakeAnswers.years||"",germanLevel:intakeAnswers.german||"",preferredLanguage:lang,onboardingCompleted:!!intakeAnswers.fullName,avatarUrl,avatarPath};
  useEffect(()=>{getCandidateWorkspace().then(async workspace=>{setIntakeAnswers(workspace.answers);setDocuments(workspace.documents);setPreferences(workspace.preferences);if(workspace.candidate){setLang(workspace.candidate.preferred_language);setAvatarPath(workspace.candidate.avatar_path||"");if(workspace.candidate.avatar_path)setAvatarUrl(await getCandidateAvatarUrl(workspace.candidate.avatar_path));setStatus(workspace.candidate.status);setReference(workspace.candidate.reference_number||"");setIntakeSubmitted(workspace.candidate.status!=="draft");setOnboarded(true)}}).catch(error=>{console.error(error);setIntakeError(persistenceCopy.en.error)}).finally(()=>{loaded.current=true;setLoading(false)})},[]);
  useEffect(()=>{const handler=(event:Event)=>{const detail=(event as CustomEvent<{url:string;path:string}>).detail;setAvatarUrl(detail.url);setAvatarPath(detail.path)};window.addEventListener("medibridge-avatar",handler);return()=>window.removeEventListener("medibridge-avatar",handler)},[]);
  useEffect(()=>{Promise.all([listPublishedJobs(),listMyInterests()]).then(([available,current])=>{setLiveJobs(available);setInterests(current)}).catch(console.error)},[]);
  useEffect(()=>{if(!loaded.current||Object.keys(intakeAnswers).length===0)return;setDraftState("saving");const timer=setTimeout(()=>saveCandidateDraft(intakeAnswers,lang).then(()=>setDraftState("saved")).catch(()=>setDraftState("error")),700);return()=>clearTimeout(timer)},[intakeAnswers,lang]);
  const openJob=(i:number)=>{setSelectedJob(i);setInterested(false);setView("job")};
  const submitIntake=async()=>{setIntakeSaving(true);setIntakeError("");try{const nextReference=await submitCandidateIntake({answers:intakeAnswers,documentFiles:intakeDocumentFiles,language:lang});setReference(nextReference);setStatus("submitted");setIntakeSubmitted(true);const workspace=await getCandidateWorkspace();setDocuments(workspace.documents);setIntakeDocumentFiles({})}catch(error){console.error(error);setIntakeError(persistenceCopy[lang].error)}finally{setIntakeSaving(false)}};
  const changeLanguage=(next:Language)=>{setLang(next);void saveCandidateLanguage(next).catch(()=>setDraftState("error"))};
  if(loading)return <main className="welcome-shell"><section className="welcome-card loading-card"><Brand/><div className="loading-mark"><ShieldCheck/></div><p className="lead">MediBridge Careers</p></section></main>;
  if(!onboarded) return <main className="welcome-shell" dir={rtl?"rtl":"ltr"}><section className="welcome-card"><Brand/><div className="welcome-visual" aria-hidden="true"><div className="passport-card"><span>MB</span><BadgeCheck/></div><div className="journey-line"><span>✦</span></div><div className="germany-card"><span>DE</span><Check/></div></div><div><p className="eyebrow">MEDIBRIDGE CAREERS</p><h1>{t.welcome}</h1><p className="lead">{t.welcomeText}</p></div><div className="welcome-actions"><button className="primary-button" onClick={()=>{setOnboarded(true);setView("intake")}}>{t.start}<ArrowRight size={18}/></button><button className="text-button" onClick={()=>setOnboarded(true)}>{t.haveAccount}</button></div><p className="privacy-line"><ShieldCheck size={16}/>{t.privacy}</p></section></main>;
  const focused=view==="job"||view==="intake"||view==="jobPreferences"||view==="settings"||view==="help";
  return <main className="app-shell" dir={rtl?"rtl":"ltr"}><div className="app-frame"><header className={`topbar ${focused?"focused":"main-header"}`}>{focused?<><button className="icon-button header-back" onClick={()=>view==="job"?setView("jobs"):setView("profile")} aria-label="Back"><ArrowLeft size={21}/></button><div className="header-brand"><Brand compact/></div><span className="header-spacer"/></>:<><div className="header-profile"><ProfileMenu lang={lang} setView={setView} account={account} compact/></div><div className="header-brand"><Brand compact/></div><button className="icon-button header-bell" aria-label="Notifications"><Bell size={20}/><i/></button></>}</header><div className="page-content">{draftState!=="idle"&&<div className={`draft-state ${draftState}`}>{draftState==="saving"?(lang==="de"?"Entwurf wird gespeichert…":lang==="ar"?"جارٍ حفظ المسودة…":"Saving draft…"):draftState==="saved"?(lang==="de"?"Entwurf gespeichert":lang==="ar"?"تم حفظ المسودة":"Draft saved"):(lang==="de"?"Speichern fehlgeschlagen":lang==="ar"?"تعذر الحفظ":"Save failed")}</div>}{view==="home"&&<Dashboard t={t} lang={lang} account={account} submitted={intakeSubmitted} status={status} documents={documents} setView={setView}/>} {view==="jobs"&&<JobsList t={t} savedJobs={savedJobs} setSavedJobs={setSavedJobs} openJob={openJob}/>} {view==="documents"&&<Documents t={t} lang={lang} documents={documents} setDocuments={setDocuments}/>} {view==="profile"&&<Profile t={t} editing={false} setEditing={()=>{}} setView={setView} lang={lang} submitted={intakeSubmitted} account={account} saving={false} onSave={()=>{}}/>} {view==="job"&&jobs[selectedJob]&&<JobDetail t={t} job={jobs[selectedJob]} interested={interested} setInterested={setInterested} saved={savedJobs.includes(selectedJob)} toggleSaved={()=>setSavedJobs(s=>s.includes(selectedJob)?s.filter(x=>x!==selectedJob):[...s,selectedJob])}/>} {view==="intake"&&<Intake lang={lang} step={intakeStep} setStep={setIntakeStep} answers={intakeAnswers} setAnswers={setIntakeAnswers} documents={intakeDocuments} setDocuments={setIntakeDocuments} setDocumentFiles={setIntakeDocumentFiles} consent={intakeConsent} setConsent={setIntakeConsent} submitted={intakeSubmitted} saving={intakeSaving} error={intakeError} reference={reference} onEdit={()=>{setIntakeSubmitted(false);setIntakeStep(intakeCopy[lang].sections.length+1)}} onSubmit={submitIntake} onDone={()=>setView("home")}/>} {view==="jobPreferences"&&<JobPreferences lang={lang} preferences={preferences} setPreferences={setPreferences}/>} {view==="settings"&&<SettingsPage lang={lang} setLang={changeLanguage}/>} {view==="help"&&<HelpPage lang={lang}/>}</div>{!focused&&<BottomNav t={t} view={view} setView={setView}/>}</div></main>;
}

function Brand({compact=false}:{compact?:boolean}){return <div className={`brand ${compact?"compact":""}`}><img className="brand-logo" src="/medibridge-logo.svg" alt="MediBridge Maghreb"/>{!compact&&<small>Careers in Germany</small>}</div>}
function Dashboard({t,lang,account,submitted,setView}:any){const p=processCopy[lang as Language];const fields=[account.fullName,account.country,account.profession,account.experience,account.germanLevel];const score=submitted?100:Math.round((fields.filter(Boolean).length/fields.length)*100);const first=(account.fullName||account.displayName||account.email||"").split(/[\s@]/)[0];const greeting=lang==="de"?`Guten Morgen, ${first}`:lang==="ar"?`صباح الخير، ${first}`:`Good morning, ${first}`;const noJobs=lang==="de"?"Sobald passende Stellen verfügbar sind, erscheinen sie hier.":lang==="ar"?"ستظهر الوظائف المناسبة هنا عند توفرها.":"Suitable positions will appear here when they are available.";return <><section className="hero-copy"><p className="eyebrow">MEDIBRIDGE CAREERS</p><h1>{greeting}</h1><p>{t.subtitle}</p></section><section className={`progress-card ${submitted?"submitted":""}`}><div className="progress-top"><div><span>{submitted?p.status:t.completion}</span><strong>{score}%</strong></div><div className="score-ring">{score}</div></div><Progress value={score} className="profile-progress"/><p>{submitted?p.response:t.completeHint}</p><button className="secondary-button" onClick={()=>setView(account.fullName?"intake":"profile")}>{submitted?p.viewStatus:t.continue}<ChevronRight size={18}/></button></section><section className="stat-grid"><article><BriefcaseBusiness/><strong>0</strong><span>{t.applications}</span></article><article><Heart/><strong>0</strong><span>{t.saved}</span></article><article className="accent"><Sparkles/><strong>0</strong><span>{t.matches}</span></article></section><SectionHeading title={t.recommended} action={t.seeAll} onClick={()=>setView("jobs")}/><div className="empty-card"><BriefcaseBusiness/><strong>{t.recommended}</strong><p>{noJobs}</p></div><section className="trust-card"><ShieldCheck/><div><strong>{t.privacy}</strong><p>{t.privacyText}</p></div></section></>}
function JobsList({t,savedJobs,setSavedJobs,openJob}:any){const[available,setAvailable]=useState<Job[]>(jobs);const[interests,setInterests]=useState<JobInterest[]>([]);useEffect(()=>{Promise.all([listPublishedJobs(),listMyInterests()]).then(([found,current])=>{jobs.splice(0,jobs.length,...found);setAvailable(found);setInterests(current)}).catch(console.error)},[]);const empty=t.home==="Start"?"Aktuell sind noch keine Stellen veröffentlicht.":t.home==="الرئيسية"?"لا توجد وظائف منشورة حالياً.":"There are no published positions yet.";return <section><div className="pilot-banner"><span>BETA</span>{t.home==="Start"?"Pilotbetrieb – dein Feedback hilft uns bei der Verbesserung.":t.home==="الرئيسية"?"نسخة تجريبية – ملاحظاتك تساعدنا على التحسين.":"Pilot release – your feedback helps us improve."}</div><div className="page-heading"><p className="eyebrow">MEDIBRIDGE</p><h1>{t.jobs}</h1><p>{t.anonymous}</p></div>{available.length===0?<div className="empty-card large"><BriefcaseBusiness/><strong>{t.jobs}</strong><p>{empty}</p></div>:<div className="job-list">{available.map((job,i)=><div className="job-wrap" key={job.id}><button aria-label="Save job" className={`save-button ${savedJobs.includes(i)?"active":""}`} onClick={()=>setSavedJobs((s:number[])=>s.includes(i)?s.filter(x=>x!==i):[...s,i])}><Heart size={19} fill={savedJobs.includes(i)?"currentColor":"none"}/></button><JobCard t={t} job={job} interested={interests.some(x=>x.job_id===job.id)} onClick={()=>openJob(i)}/></div>)}</div>}</section>}
function JobCard({t,job,interested,onClick}:any){return <button className="job-card" onClick={onClick}><div className="employer-icon"><BriefcaseBusiness/></div><div className="job-card-body"><span className="verified-label"><BadgeCheck size={14}/>{t.verified}</span><h3>{job.title}</h3><div className="job-meta"><span><MapPin size={15}/>{job.region}</span><span><Clock3 size={15}/>{job.employment_type==="training"?"Training":t.fulltime}</span></div><div className="job-footer"><strong>{interested?t.interestSent:(job.salary_text||t.anonymous)}</strong><ChevronRight size={19}/></div></div></button>}
function JobDetail({t,job,interested,setInterested,saved,toggleSaved}:any){const[busy,setBusy]=useState(false);return <section className="job-detail"><div className="detail-hero"><div className="employer-icon large"><BriefcaseBusiness/></div><span className="verified-label light"><BadgeCheck size={15}/>{t.verified}</span><h1>{job.title}</h1><p><MapPin size={16}/>{job.region} · {job.employment_type==="training"?"Training":t.fulltime}</p></div><div className="detail-body"><div className="detail-tags"><span>{job.salary_text||t.anonymous}</span><span>{job.german_level||t.language}</span></div><p className="anonymity"><ShieldCheck size={18}/>{t.anonymous}</p><h2>{t.about}</h2><p>{job.description}</p><h2>{t.support}</h2><p>{job.support_text||t.supportText}</p></div><div className="sticky-actions"><button aria-label="Save job" className={`square-button ${saved?"active":""}`} onClick={toggleSaved}><Heart fill={saved?"currentColor":"none"}/></button><button disabled={busy||interested} className={`primary-button ${interested?"success":""}`} onClick={async()=>{setBusy(true);try{await expressJobInterest(job.id);setInterested(true)}finally{setBusy(false)}}}>{interested?<><Check/>{t.interestSent}</>:<>{busy?"…":t.apply}<ArrowRight size={18}/></>}</button></div></section>}
function Documents({t,lang,documents,setDocuments}:any){const [busy,setBusy]=useState("");const [message,setMessage]=useState("");const [selectedType,setSelectedType]=useState("passport");const uploadRef=useRef<HTMLInputElement>(null);const replaceRef=useRef<HTMLInputElement>(null);const replacing=useRef<CandidateDocument|null>(null);const c=lang==="de"?{progress:"Dokumentenstatus",complete:"Pflichtunterlagen vollständig",missing:"Pflichtunterlagen fehlen",preview:"Ansehen",download:"Herunterladen",replace:"Ersetzen",remove:"Löschen",add:"Dokument hinzufügen",select:"Dokumenttyp",pending:"In Prüfung",verified:"Verifiziert",rejected:"Nachbesserung nötig",empty:"Noch nicht hochgeladen",size:"Max. 10 MB · PDF, JPG oder PNG",success:"Dokument wurde hochgeladen.",invalid:"Nur PDF, JPG oder PNG bis maximal 10 MB."}:lang==="ar"?{progress:"حالة المستندات",complete:"المستندات الإلزامية مكتملة",missing:"المستندات الإلزامية ناقصة",preview:"عرض",download:"تنزيل",replace:"استبدال",remove:"حذف",add:"إضافة مستند",select:"نوع المستند",pending:"قيد المراجعة",verified:"تم التحقق",rejected:"يحتاج إلى تصحيح",empty:"لم يتم الرفع بعد",size:"حتى 10 ميغابايت · PDF أو JPG أو PNG",success:"تم رفع المستند.",invalid:"يُسمح فقط بملفات PDF أو JPG أو PNG حتى 10 ميغابايت."}:{progress:"Document status",complete:"Required documents complete",missing:"Required documents missing",preview:"Preview",download:"Download",replace:"Replace",remove:"Delete",add:"Add document",select:"Document type",pending:"In review",verified:"Verified",rejected:"Needs correction",empty:"Not uploaded yet",size:"Max. 10 MB · PDF, JPG or PNG",success:"Document uploaded.",invalid:"Only PDF, JPG or PNG files up to 10 MB are allowed."};const types=[{id:"passport",label:t.passport,required:true},{id:"qualification",label:t.diploma,required:true},{id:"language",label:t.languageCert,required:false},{id:"reference",label:t.workRef,required:false},{id:"general",label:lang==="de"?"Weiteres Dokument":lang==="ar"?"مستند آخر":"Other document",required:false}];const requiredComplete=types.filter(x=>x.required).every(type=>documents.some((d:CandidateDocument)=>d.document_type===type.id&&d.verification_status!=="rejected"));const statusLabel=(d:CandidateDocument)=>d.verification_status==="verified"?c.verified:d.verification_status==="rejected"?c.rejected:c.pending;const open=async(d:CandidateDocument,download=false)=>{try{const url=await getCandidateDocumentUrl(d,download);window.open(url,"_blank","noopener,noreferrer")}catch{setMessage(persistenceCopy[lang as Language].error)}};const upload=async(file?:File)=>{if(!file)return;setBusy("upload");setMessage("");try{const document=await uploadCandidateDocument(selectedType,file);setDocuments((current:CandidateDocument[])=>[document,...current]);setMessage(c.success)}catch(error){setMessage(error instanceof Error&&(error.message==="FILE_TOO_LARGE"||error.message==="INVALID_FILE_TYPE")?c.invalid:persistenceCopy[lang as Language].error)}finally{setBusy("");if(uploadRef.current)uploadRef.current.value=""}};const replace=async(file?:File)=>{const old=replacing.current;if(!file||!old)return;setBusy(old.id);try{const next=await replaceCandidateDocument(old,file);setDocuments((current:CandidateDocument[])=>[next,...current.filter(item=>item.id!==old.id)]);setMessage(c.success)}catch(error){setMessage(error instanceof Error&&(error.message==="FILE_TOO_LARGE"||error.message==="INVALID_FILE_TYPE")?c.invalid:persistenceCopy[lang as Language].error)}finally{setBusy("");replacing.current=null;if(replaceRef.current)replaceRef.current.value=""}};const remove=async(d:CandidateDocument)=>{setBusy(d.id);try{await deleteCandidateDocument(d);setDocuments((current:CandidateDocument[])=>current.filter(item=>item.id!==d.id))}catch{setMessage(persistenceCopy[lang as Language].error)}finally{setBusy("")}};return <section><div className="page-heading"><p className="eyebrow">MEDIBRIDGE</p><h1>{t.docsTitle}</h1><p>{t.docsSubtitle}</p></div><section className={`verification-card ${requiredComplete?"documents-complete":""}`}><div className="verification-icon"><BadgeCheck/></div><div><strong>{c.progress}</strong><p>{requiredComplete?c.complete:c.missing}</p></div><span>{types.slice(0,4).filter(type=>documents.some((d:CandidateDocument)=>d.document_type===type.id)).length}/4</span></section>{message&&<p className="document-message">{message}</p>}<div className="document-categories">{types.slice(0,4).map(type=>{const items=documents.filter((d:CandidateDocument)=>d.document_type===type.id);return <section className="document-category" key={type.id}><header><div><strong>{type.label}</strong><span>{type.required?(lang==="de"?"Pflicht":lang==="ar"?"مطلوب":"Required"):(lang==="de"?"Optional":lang==="ar"?"اختياري":"Optional")}</span></div>{items.length===0&&<button onClick={()=>{setSelectedType(type.id);uploadRef.current?.click()}}><UploadCloud size={16}/>{c.add}</button>}</header>{items.length===0?<p className="document-empty"><FileText/>{c.empty}</p>:items.map((d:CandidateDocument)=><article className={`document-record ${d.verification_status}`} key={d.id}><div className="doc-icon done"><FileCheck2/></div><div className="document-record-main"><strong>{d.file_name}</strong><span>{d.file_size?`${(d.file_size/1024/1024).toFixed(1)} MB · `:""}{statusLabel(d)}</span>{d.verification_note&&<p>{d.verification_note}</p>}</div><div className="document-actions"><button title={c.preview} onClick={()=>void open(d)}><Eye/></button><button title={c.download} onClick={()=>void open(d,true)}><Download/></button><button title={c.replace} disabled={!!busy} onClick={()=>{replacing.current=d;replaceRef.current?.click()}}><RefreshCw/></button><button title={c.remove} disabled={!!busy} onClick={()=>void remove(d)}>{busy===d.id?"…":"×"}</button></div></article>)}</section>})}</div><div className="document-upload-panel"><label><span>{c.select}</span><select value={selectedType} onChange={e=>setSelectedType(e.target.value)}>{types.map(type=><option value={type.id} key={type.id}>{type.label}</option>)}</select></label><input ref={uploadRef} type="file" hidden accept="application/pdf,image/jpeg,image/png" onChange={e=>void upload(e.target.files?.[0])}/><input ref={replaceRef} type="file" hidden accept="application/pdf,image/jpeg,image/png" onChange={e=>void replace(e.target.files?.[0])}/><button disabled={!!busy} className="upload-zone" onClick={()=>uploadRef.current?.click()}><UploadCloud/><strong>{busy==="upload"?"…":c.add}</strong><span>{c.size}</span></button></div></section>}
function Profile({t,editing,setEditing,setView,lang,submitted,account,saving,onSave}:any){const p=processCopy[lang as Language];const [draft,setDraft]=useState<Account>(account);useEffect(()=>setDraft(account),[account]);const fields=[{key:"fullName",label:t.name,type:"text"},{key:"country",label:t.country,type:"text"},{key:"profession",label:t.role,type:"text"},{key:"experience",label:t.experience,type:"text"},{key:"germanLevel",label:t.level,type:"text"}] as const;const update=(key:string,value:string)=>setDraft(current=>({...current,[key]:value}));return <section><div className="profile-header"><ProfileMenu lang={lang} setView={setView} account={account}/><div><h1>{t.profileTitle}</h1><p>{account.email}</p></div></div><AvatarUpload lang={lang} account={account}/>{account.fullName&&<button className="intake-entry" onClick={()=>setView("intake")}><span>{submitted?<BadgeCheck/>:<ClipboardList/>}<strong>{submitted?p.viewStatus:t.continue}</strong></span><ChevronRight/></button>}<section className="profile-section"><div className="section-row"><h2>{t.personal}</h2><button className="inline-action" disabled={saving} onClick={()=>editing?onSave({...draft,onboardingCompleted:true}):setEditing(true)}>{saving?"…":editing?t.save:t.edit}</button></div>{fields.map(field=><label className="profile-field" key={field.key}><span>{field.label}</span>{editing?<input required={field.key==="fullName"} value={draft[field.key]??""} onChange={e=>update(field.key,e.target.value)}/>:<strong>{account[field.key]||"—"}</strong>}</label>)}</section><section className="cv-card"><div className="cv-icon"><FileText/></div><div><span className="soon-label">{t.comingSoon}</span><h2>{t.cvTitle}</h2><p>{t.cvText}</p></div></section><section className="trust-card"><ShieldCheck/><div><strong>{t.privacy}</strong><p>{t.privacyText}</p></div></section></section>}
function AvatarUpload({lang,account}:{lang:Language;account:Account}){const input=useRef<HTMLInputElement>(null);const[busy,setBusy]=useState(false);const[error,setError]=useState("");const upload=async(file?:File)=>{if(!file)return;setBusy(true);setError("");try{const result=await uploadCandidateAvatar(file);window.dispatchEvent(new CustomEvent("medibridge-avatar",{detail:result}))}catch(e){setError(e instanceof Error&&e.message==="FILE_TOO_LARGE"?(lang==="de"?"Maximal 5 MB erlaubt.":lang==="ar"?"الحد الأقصى 5 ميغابايت":"Maximum 5 MB allowed."):(lang==="de"?"Profilbild konnte nicht gespeichert werden.":lang==="ar"?"تعذر حفظ صورة الملف الشخصي":"Profile picture could not be saved."))}finally{setBusy(false);if(input.current)input.current.value=""}};const remove=async()=>{setBusy(true);try{await deleteCandidateAvatar(account.avatarPath);window.dispatchEvent(new CustomEvent("medibridge-avatar",{detail:{url:"",path:""}}))}finally{setBusy(false)}};return <section className="avatar-upload-card"><div className="profile-photo large">{account.avatarUrl?<img src={account.avatarUrl} alt="Profile"/>:<UserRound/>}</div><div><strong>{lang==="de"?"Profilbild":lang==="ar"?"صورة الملف الشخصي":"Profile picture"}</strong><span>JPG, PNG, WebP · 5 MB</span><div><button disabled={busy} onClick={()=>input.current?.click()}><Camera/>{busy?"…":account.avatarUrl?(lang==="de"?"Ersetzen":lang==="ar"?"استبدال":"Replace"):(lang==="de"?"Hochladen":lang==="ar"?"رفع":"Upload")}</button>{account.avatarUrl&&<button className="remove" disabled={busy} onClick={remove}>{lang==="de"?"Löschen":lang==="ar"?"حذف":"Delete"}</button>}</div></div><input ref={input} hidden type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>void upload(e.target.files?.[0])}/>{error&&<p>{error}</p>}</section>}
function ProfileMenu({lang,setView,account,compact=false}:any){const m=menuCopy[lang as Language];const displayName=account.fullName||account.displayName||account.email;const initials=displayName.split(/\s+/).map((part:string)=>part[0]).join("").slice(0,2).toUpperCase()||"MB";const subtitle=[account.profession,account.germanLevel].filter(Boolean).join(" · ");const roleLabel=account.role==="recruiter"?"MediBridge Team":m.candidate;const logout=lang==="de"?"Abmelden":lang==="ar"?"تسجيل الخروج":"Sign out";const items=[{view:"profile",label:m.profile,icon:UserRound},{view:"jobPreferences",label:m.jobPreferences,icon:SlidersHorizontal},{view:"settings",label:m.settings,icon:Settings},{view:"help",label:m.help,icon:HelpCircle}];const avatar=account.avatarUrl?<img className="avatar-image" src={account.avatarUrl} alt={displayName}/>:initials;return <Sheet><SheetTrigger asChild><button className={compact?"mini-avatar":"avatar avatar-button"} aria-label={m.profile}>{avatar}</button></SheetTrigger><SheetContent side={lang==="ar"?"right":"left"} className="profile-menu-sheet" showCloseButton><SheetHeader className="profile-menu-header"><SheetTitle className="sr-only">{m.profile}</SheetTitle><SheetDescription className="sr-only">MediBridge candidate menu</SheetDescription><div className="menu-avatar">{avatar}</div><div><small>{roleLabel}</small><strong>{displayName}</strong><p>{subtitle||account.email}</p></div></SheetHeader><nav className="profile-menu-nav">{items.map(({view,label,icon:Icon})=><SheetClose asChild key={view}><button onClick={()=>setView(view)}><span><Icon/>{label}</span><ChevronRight/></button></SheetClose>)}<a className="menu-signout" href="/signout-with-chatgpt?return_to=/"><span><LogOut/>{logout}</span></a></nav><div className="profile-menu-footer"><img src="/medibridge-logo.svg" alt="MediBridge Maghreb"/><p>Careers in Germany</p></div></SheetContent></Sheet>}
function JobPreferences({lang,preferences,setPreferences}:any){const m=menuCopy[lang as Language];const [saving,setSaving]=useState(false);const [saved,setSaved]=useState(false);const fields=[{key:"desired_role",label:m.desiredRole},{key:"preferred_region",label:m.preferredRegion},{key:"possible_start",label:m.startDate},{key:"workplace",label:m.workplace}];const persist=async()=>{setSaving(true);setSaved(false);try{await saveJobPreferences(preferences);setSaved(true)}finally{setSaving(false)}};return <section className="subpage"><div className="subpage-icon"><SlidersHorizontal/></div><h1>{m.preferencesTitle}</h1><p>{m.preferencesText}</p><div className="preference-list">{fields.map(field=><label key={field.key}><span>{field.label}</span><input value={preferences[field.key]||""} onChange={e=>setPreferences((current:JobPreferences)=>({...current,[field.key]:e.target.value}))}/></label>)}</div>{saved&&<p className="status-done">{lang==="de"?"Job-Wünsche gespeichert":lang==="ar"?"تم حفظ التفضيلات":"Preferences saved"}</p>}<button disabled={saving} className="primary-button" onClick={persist}><Check/>{saving?"…":m.save}</button></section>}
function SettingsPage({lang,setLang}:any){const m=menuCopy[lang as Language];const languageTitle=lang==="de"?"Sprache":lang==="ar"?"اللغة":"Language";return <section className="subpage"><div className="subpage-icon"><Settings/></div><h1>{m.settingsTitle}</h1><p>{m.settingsText}</p><section className="language-settings standalone"><div className="language-setting-title"><Languages/><div><strong>{languageTitle}</strong><span>{lang==="de"?"App-Sprache auswählen":lang==="ar"?"اختر لغة التطبيق":"Choose app language"}</span></div></div><div className="language-options">{[{id:"de",label:"Deutsch"},{id:"en",label:"English"},{id:"ar",label:"العربية"}].map(option=><button key={option.id} className={lang===option.id?"active":""} onClick={()=>setLang(option.id)}>{option.label}{lang===option.id&&<Check size={14}/>}</button>)}</div></section><section className="settings-note"><ShieldCheck/><div><strong>{copy[lang as Language].privacy}</strong><p>{copy[lang as Language].privacyText}</p></div></section></section>}
function HelpPage({lang}:any){const m=menuCopy[lang as Language];const items=[{label:m.faq,icon:MessageCircleQuestion,href:"mailto:hi.sersar@gmail.com?subject=MediBridge%20FAQ"},{label:m.contact,icon:HelpCircle,href:"mailto:hi.sersar@gmail.com"},{label:m.privacy,icon:ShieldCheck,href:"/privacy"}];return <section className="subpage"><div className="subpage-icon"><HelpCircle/></div><h1>{m.helpTitle}</h1><p>{m.helpText}</p><div className="help-list">{items.map(({label,icon:Icon,href})=><a href={href} key={label}><span><Icon/>{label}</span><ChevronRight/></a>)}</div></section>}
function Intake({lang,step,setStep,answers,setAnswers,documents,setDocuments,setDocumentFiles,consent,setConsent,submitted,saving,error,reference,onEdit,onSubmit,onDone}:any){
  const c=intakeCopy[lang as Language];const p=processCopy[lang as Language];const questionTotal=c.sections.length;const total=questionTotal+2;const icons=[UserRound,Stethoscope,GraduationCap,BriefcaseBusiness,Globe2,PlaneTakeoff];
  if(submitted)return <section className="intake-success status-page"><div className="success-badge"><BadgeCheck/></div><p className="eyebrow">MEDIBRIDGE CAREERS</p><span className="status-pill"><Clock3 size={14}/>{p.status}</span><h1>{p.submitted}</h1><p>{p.submittedText}</p><div className="reference-card"><span>{p.referenceNo}</span><strong>{reference||"—"}</strong></div><p className="response-note">{p.response}</p><div className="next-steps"><h2>{p.nextSteps}</h2>{[p.next1,p.next2,p.next3].map((item,i)=><div key={item}><i>{i+1}</i><span>{item}</span></div>)}</div><button className="secondary-button" onClick={onEdit}>{p.edit}</button><button className="primary-button" onClick={onDone}>{p.dashboard}<ArrowRight size={18}/></button></section>;
  const update=(id:string,value:string)=>setAnswers((current:Record<string,string>)=>({...current,[id]:value}));
  const shell=(title:string,hint:string,Icon:any,body:any)=><section className="intake-page"><div className="intake-top"><div><p className="eyebrow">{c.step} {step+1} {c.of} {total}</p><h1>{c.title}</h1><p>{c.intro}</p></div><div className="intake-icon"><Icon/></div></div><Progress value={((step+1)/total)*100} className="intake-progress"/><div className="intake-section-heading"><h2>{title}</h2><p>{hint}</p></div>{body}<p className="intake-privacy"><ShieldCheck size={15}/>{copy[lang as Language].privacyText}</p></section>;
  if(step<questionTotal){const section=c.sections[step];const Icon=icons[step];const complete=section.questions.every((q:any)=>(answers[q.id]??"").trim().length>0);return shell(section.title,section.hint,Icon,<form className="intake-form" onSubmit={e=>{e.preventDefault();if(complete)setStep(step+1)}}>{section.questions.map((q:any)=><div className="question-field" key={q.id}><label>{q.label}<span>*</span></label>{q.type==="choice"?<div className="choice-grid">{q.options.map((option:string)=><button type="button" key={option} className={answers[q.id]===option?"selected":""} onClick={()=>update(q.id,option)}><i>{answers[q.id]===option&&<Check size={13}/>}</i>{option}</button>)}</div>:q.type==="textarea"?<textarea rows={4} value={answers[q.id]??""} placeholder={q.placeholder} onChange={e=>update(q.id,e.target.value)}/>:<input type={q.type} value={answers[q.id]??""} placeholder={q.placeholder} onChange={e=>update(q.id,e.target.value)}/>}</div>)}<div className="intake-actions">{step>0&&<button type="button" className="back-button" onClick={()=>setStep(step-1)}><ArrowLeft size={17}/>{c.back}</button>}<button type="submit" className="primary-button" disabled={!complete}>{c.next}<ArrowRight size={18}/></button></div></form>)}
  if(step===questionTotal){const docTypes=[{id:"passport",label:p.passport,required:true},{id:"qualification",label:p.qualification,required:true},{id:"language",label:p.language,required:false},{id:"reference",label:p.reference,required:false}];const complete=!!documents.passport&&!!documents.qualification;return shell(p.documents,p.documentsHint,UploadCloud,<div className="intake-form"><div className="intake-document-grid">{docTypes.map(doc=><label className={`intake-document ${documents[doc.id]?"done":""}`} key={doc.id}><input type="file" accept=".pdf,.jpg,.jpeg,.png" onChange={e=>{const file=e.target.files?.[0];if(file){setDocuments((current:Record<string,string>)=>({...current,[doc.id]:file.name}));setDocumentFiles((current:Record<string,File>)=>({...current,[doc.id]:file}))}}}/><div className="doc-icon">{documents[doc.id]?<FileCheck2/>:<FileText/>}</div><div><strong>{doc.label}</strong><span>{documents[doc.id]?documents[doc.id]:doc.required?p.required:p.optional}</span></div><b>{documents[doc.id]?p.uploaded:p.choose}</b></label>)}</div><div className="intake-actions"><button type="button" className="back-button" onClick={()=>setStep(step-1)}><ArrowLeft size={17}/>{c.back}</button><button type="button" className="primary-button" disabled={!complete} onClick={()=>setStep(step+1)}>{c.next}<ArrowRight size={18}/></button></div></div>)}
  const answeredSections=c.sections.map((section:any,index:number)=>({title:section.title,index,items:section.questions.map((q:any)=>({label:q.label,value:answers[q.id]}))}));return shell(p.review,p.reviewHint,ClipboardList,<div className="review-wrap"><div className="review-groups">{answeredSections.map(group=><section key={group.title}><header><strong>{group.title}</strong><button onClick={()=>setStep(group.index)}>{p.edit}</button></header>{group.items.map((item:any)=><div key={item.label}><span>{item.label}</span><b>{item.value}</b></div>)}</section>)}</div><section className="review-documents"><header><strong>{p.files}</strong><button onClick={()=>setStep(questionTotal)}>{p.edit}</button></header>{Object.entries(documents).map(([id,name])=><div key={id}><FileCheck2/><span>{name as string}</span></div>)}</section><label className="consent-row"><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)}/><span>{p.consent}</span></label>{error&&<p className="submission-error">{error}</p>}<div className="intake-actions"><button type="button" className="back-button" disabled={saving} onClick={()=>setStep(step-1)}><ArrowLeft size={17}/>{c.back}</button><button type="button" className="primary-button" disabled={!consent||saving} onClick={onSubmit}>{saving?persistenceCopy[lang as Language].saving:p.submit}{!saving&&<Check size={18}/>}</button></div></div>)}
function SectionHeading({title,action,onClick}:any){return <div className="section-heading"><h2>{title}</h2><button onClick={onClick}>{action}<ChevronRight size={16}/></button></div>}
function BottomNav({t,view,setView}:any){const items=[{id:"home",icon:Home,label:t.home},{id:"jobs",icon:BriefcaseBusiness,label:t.jobs},{id:"documents",icon:FileText,label:t.documents},{id:"profile",icon:UserRound,label:t.profile}];return <nav className="bottom-nav" aria-label="Primary">{items.map(({id,icon:Icon,label})=><button className={view===id?"active":""} key={id} onClick={()=>setView(id)}><Icon size={21}/><span>{label}</span>{view===id&&<i/>}</button>)}</nav>}
